const clean = (x, n) => String(x ?? '').replace(/\s+/g, ' ').trim().slice(0, n);
// [FS-SHARE-CARD] 抖音刷到的分享改成「视频卡片 + 一句话」：这里只把这条视频的信息塞进 reason，
