const hasCard = target.startsWith('douyin:') && typeof this.douyinShareCard === 'function' && /^\d{8,}$/.test(String(videoId ?? ''));
const reason = hasCard
	? `${SHARE_CARD_TAG}${JSON.stringify({
		videoId: String(videoId),
		title: clean(title, 60),
		desc: clean(title, 120),
		author: clean(author, 20),
		impression: clean(impression, 120),
		platform: String(platform ?? '抖音')
	})}`
	: `你刚在${platform}刷到一个视频《${clean(title, 60) || '没写标题'}》${author ? `（${clean(author, 20)}）` : ''}，链接 ${url} 。` +
		`你看完觉得：${clean(impression, 120)}。很想发给对方看看：把链接原样发出去，再用一两句话说说你为什么想给 ta 看（像随手转给朋友，别写成推荐语、别复述标题）`;

/** 她自己起意的待办（占每日主动配额） */
const BOT_ORIGINS = new Set(['dream', 'share']);

/** [FS-SHARE-CARD] queueShare 把「刷到的那条视频」存在 pending.reason 里的前缀（要发视频卡片的那条）。 */
const SHARE_CARD_TAG = '[FS-SHARE-CARD]';

/**
 * [FS-SHARE-CARD] 解析 queueShare 存下的卡片信息；不是卡片（老格式 / 别的来源）返回 null。
 * fallback 是卡片这条路不通时退回去发的文字（链接 + 感受），和改造前的老路一样。
 */
function parseShareCard(reason) {
	const s = String(reason ?? '');
	if (!s.startsWith(SHARE_CARD_TAG)) return null;
	try {
		const o = JSON.parse(s.slice(SHARE_CARD_TAG.length));
		const videoId = String(o?.videoId ?? '');
		if (!/^\d{8,}$/.test(videoId)) return null;
		const title = String(o?.title ?? '').slice(0, 60);
		const impression = String(o?.impression ?? '').slice(0, 120);
		const platform = String(o?.platform ?? '抖音').slice(0, 10);
		const url = `https://www.douyin.com/video/${videoId}`;
		return {
			videoId,
			title,
			desc: String(o?.desc ?? '').slice(0, 120),
			impression,
			author: String(o?.author ?? '').slice(0, 20),
			fallback: `你刚在${platform}刷到一个视频《${title || '没写标题'}》${o?.author ? `（${String(o.author).slice(0, 20)}）` : ''}，链接 ${url} 。` +
				(impression !== '' ? `你看完觉得：${impression}。` : '') +
				'很想发给对方看看：把链接原样发出去，再用一两句话说说你为什么想给 ta 看（像随手转给朋友，别写成推荐语、别复述标题）'
		};
	} catch { return null; }
}

