async deliverOne(d, nowVirtual) {
	const botInitiated = BOT_ORIGINS.has(d.origin ?? 'user');
	// [FS-SHARE-CARD] 刷到的分享先发视频卡片（不是链接）。卡片这条路不通（浏览器没开 / 没登录 /
	// 分享面板没弹出来）就退回老路：把链接发到 QQ 主人私聊，别让这条分享烂在库里。
	// 同一条只试两次卡片，两次都不行就老实发链接，免得每条分享都白开一遍浏览器。
	let row = d;
	const card = d.origin === 'share' && this.douyinShareCard !== null ? parseShareCard(d.reason) : null;
	if (card !== null && Number(d.attempts ?? 0) < 2) {
		this.lastProactiveReal.set('douyin', Date.now());
		const r = await this.douyinShareCard(card)
			.catch((error) => ({ ok: false, error: String(error instanceof Error ? error.message : error) }));
		this.lastProactiveReal.set('douyin', Date.now());
		if (r?.ok === true) {
			this.db.prepare("UPDATE pending SET status = 'done' WHERE id = ?").run(d.id);
			this.db.prepare(`
				UPDATE day SET proactive_count = proactive_count + 1, last_proactive_at = ?
				WHERE character_id = 'feiyu' AND date = ?
			`).run(nowVirtual, this.clock.getRoleDateParts().dateStr);
			this.log('info', `[fish-soul] 刷到的视频已用卡片分享给 ${d.channel_id}` +
				(r?.text ? `，还补了一句：${String(r.text).slice(0, 20)}` : '（这次没补话）'));
			return true;
		}
		this.log('warn', `[fish-soul] 抖音视频卡片没发成（${d.channel_id}）：${r?.error ?? '未知'}`);
		const qq = this.masterChannel(this.getConfig().proactive ?? {});
		if (qq !== '') row = { ...d, channel_id: qq, reason: card.fallback };
		else row = null; // 连 QQ 主人私聊都没设：只能算这次没发出去，走下面的退避重试
	}
	const platform = platformOf(row?.channel_id ?? d.channel_id);
	const meta = { origin: d.origin === 'share' ? 'share' : botInitiated ? 'dream' : 'user' };
	// 无论成败都计物理冷却，防止加速模式连发封号
	this.lastProactiveReal.set(platform, Date.now());
	let ok = false;
	if (row !== null) {
		try {
			ok = (await this.deliver(row.channel_id, row.reason, meta)) === true;
		} catch (error) {
			this.log('error', `[fish-soul] 主动开口失败（${row.channel_id}）：${String(error instanceof Error ? error.message : error)}`);
		}
	}
	this.lastProactiveReal.set(platform, Date.now());
